// The dashboard signs in to the same Firebase project as the mobile app
// ("safarichap") as the Web app "safarichap_admin". Generated by
//   flutterfire configure --project=safarichap --platforms=web
// A build can point at another Web app with
//   --dart-define=FIREBASE_WEB_API_KEY=... --dart-define=FIREBASE_WEB_APP_ID=...
import 'package:firebase_core/firebase_core.dart' show FirebaseOptions;

class DefaultFirebaseOptions {
  static const _apiKey = String.fromEnvironment(
    'FIREBASE_WEB_API_KEY',
    defaultValue: 'AIzaSyALQFBPt7BmrrWua5UUeBfVtiku1fn-T2c',
  );
  static const _appId = String.fromEnvironment(
    'FIREBASE_WEB_APP_ID',
    defaultValue: '1:821444152681:web:8d6a821ca7e9a06c9141f8',
  );

  static bool get isConfigured => _apiKey.isNotEmpty && _appId.isNotEmpty;

  static FirebaseOptions get currentPlatform => web;

  static const FirebaseOptions web = FirebaseOptions(
    apiKey: _apiKey,
    appId: _appId,
    messagingSenderId: '821444152681',
    projectId: 'safarichap',
    authDomain: 'safarichap.firebaseapp.com',
    storageBucket: 'safarichap.firebasestorage.app',
  );
}
